// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(bytes32 g, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(g != bytes32(0));

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g);

        // target block is the block recorded at lock time; roll past it.
        // Foundry's blockhash() returns bytes32(0) for blocks outside the
        // execution history, so the settled answer is keccak256(bytes32(0)).
        vm.roll(block.number + 2);

        uint256 balBefore = actor.balance;
        vm.prank(actor);
        c.settle();
        uint256 balAfter = actor.balance;

        bytes32 answer = keccak256(abi.encodePacked(bytes32(0)));
        bool paid = (balAfter == balBefore + 2 ether);

        assertTrue(paid == (g == answer));
    }
}
